const today = new Date().toISOString().slice(0,10);
function unwrap(node){ const items = $items(node); if(!items.length) return null; const j = items[0].json; if (j && typeof j === 'object' && 'data' in j && !('issues' in j) && !('messages' in j) && !Array.isArray(j)) return j.data; return j; }
function asArray(x){ return Array.isArray(x) ? x : (x ? [x] : []); }
function normGithub(raw){ return asArray(raw).filter(c => c && c.commit).map(c => ({source:'github', id:c.sha, text:`[GitHub] ${(c.commit.message||'').split('\n')[0]} (${(c.sha||'').slice(0,7)})`, ts:c.commit.author && c.commit.author.date || ''})); }
function normRedmine(raw){ const obj = (raw && typeof raw === 'object') ? raw : {}; const issues = obj.issues || []; return issues.map(i => ({source:'redmine', id:'RM-'+i.id, text:`[Redmine #${i.id}] [${(i.project||{}).name||'?'}] ${i.subject} — ${(i.status||{}).name||'?'} (updated ${(i.updated_on||'').slice(0,10)})`, ts: i.updated_on || ''})); }
function normSlack(raw){ const obj = (raw && typeof raw === 'object') ? raw : {}; const msgs = obj.messages || []; return msgs.filter(m => m && m.type === 'message' && m.text && !m.subtype).map(m => ({source:'slack', id:m.ts, text:`[Slack] ${m.text.slice(0,240)}`, ts:m.ts})); }
const gh = normGithub(unwrap('GitHub Commits'));
const rm = normRedmine(unwrap('Redmine Issues'));
const sl = normSlack(unwrap('Slack Messages'));
const all = [...gh, ...rm, ...sl];
const seen = new Set();
const dd = all.filter(r => { const k = r.source+':'+r.id; if(seen.has(k)) return false; seen.add(k); return true; });
function grp(src){ const l = dd.filter(r=>r.source===src).map(r=>'• '+r.text); return l.length ? l.join('\n') : '• (nothing)'; }
const activity = ['Date: '+today,'','GitHub (last 24h):', grp('github'), '','Redmine (assigned to me, last 7d):', grp('redmine'), '','Slack (today):', grp('slack')].join('\n');
const counts = { github: gh.length, redmine: rm.length, slack: sl.length, total: gh.length+rm.length+sl.length };
return [{ json: { activity, counts, items: dd, session_id: $env.STANDUP_SESSION_ID, post_channel: $env.SLACK_POST_CHANNEL_ID } }];

// Validate Input — gate before Claude
const j = $json || {};
const errors = [];
if (typeof j.activity !== 'string' || j.activity.trim().length === 0) errors.push('activity must be a non-empty string');
const c = j.counts || {};
const totalOk = typeof c.total === 'number' || (typeof c.github === 'number' && typeof c.redmine === 'number' && typeof c.slack === 'number');
if (!totalOk) errors.push('counts.total (or github/redmine/slack) must be numeric');
if ('items' in j && !Array.isArray(j.items)) errors.push('items must be an array when present');
let forceFail = $env.STANDUP_FORCE_FAIL;
try { const wb = $('Webhook (MCP entry)').first().json.body || $('Webhook (MCP entry)').first().json; if (wb && wb.force_fail) forceFail = wb.force_fail; } catch(e) {}
if (forceFail === 'input') errors.push('forced failure (force_fail=input)');
const valid = errors.length === 0;
const total = typeof c.total === 'number' ? c.total : (c.github||0)+(c.redmine||0)+(c.slack||0);
console.log(`[standup][input]  valid=${valid}  total=${total}  errors=${JSON.stringify(errors)}`);
return [{ json: { ...j, valid, errors, _stage: 'input' } }];

