// Validate Output — gate before Slack post
const j = $json || {};
const text = (j.output || '').toString();
const errors = [];
if (j.success === false) errors.push('claude node reported success=false');
if (text.trim().length === 0) errors.push('claude output is empty');
for (const s of ['Yesterday','Today','Blockers']) {
  if (!new RegExp(`\\*${s}\\*`).test(text)) errors.push(`missing section: ${s}`);
}
let forceFail = $env.STANDUP_FORCE_FAIL;
try { const wb = $('Webhook (MCP entry)').first().json.body || $('Webhook (MCP entry)').first().json; if (wb && wb.force_fail) forceFail = wb.force_fail; } catch(e) {}
if (forceFail === 'output') errors.push('forced failure (force_fail=output)');
const valid = errors.length === 0;
console.log(`[standup][output] valid=${valid} len=${text.length}  errors=${JSON.stringify(errors)}`);
return [{ json: { ...j, valid, errors, _stage: 'output' } }];

const out = $('Generate Standup').item.json.output || '';
const counts = ($('Merge & Dedup').item.json.counts) || {github:0,redmine:0,slack:0};
const today = new Date().toISOString().slice(0,10);
let body = out
  .replace(/\*\*(.+?)\*\*/g, '*$1*')
  .replace(/^- /gm, '• ')
  .replace(/^\*Yesterday\*/m, ':white_check_mark: *Yesterday*')
  .replace(/^\*Today\*/m,     ':dart: *Today*')
  .replace(/^\*Blockers\*/m,  ':warning: *Blockers*');
const payload = {
  channel: $env.SLACK_POST_CHANNEL_ID,
  text: `:clipboard: Daily Standup — ${today}`,
  blocks: [
    { type: 'header',  text: { type: 'plain_text', text: `📋 Daily Standup — ${today}`, emoji: true } },
    { type: 'context', elements: [ { type: 'mrkdwn', text: `_Generated by_ *Claude Sonnet 4.6* _via_ *n8n* • session \`${$env.STANDUP_SESSION_ID}\`` } ] },
    { type: 'divider' },
    { type: 'section', text: { type: 'mrkdwn', text: body } },
    { type: 'divider' },
    { type: 'context', elements: [ { type: 'mrkdwn', text: `:bar_chart: \`${counts.github}\` commits · \`${counts.redmine}\` Redmine issues · \`${counts.slack}\` Slack msgs` } ] },
  ],
};
return [{ json: payload }];
